#!/usr/bin/env python3
"""Clean up E2E leftovers on GitHub and GitHub Enterprise.

E2E teardown closes PRs, deletes branches and deletes per-test repositories,
but cancelled or failed runs skip it. This script removes what they leave
behind, older than --hours:

  * open PRs whose head branch was generated by a test,
  * branches generated by a test (pac-e2e-test-xxxxx, pac-e2e-ns-xxxxx, ...),
  * per-test repositories (pac-e2e-test-xxxxx) in the GHE webhook org.

Only test-generated names are considered. A branch is kept when it is the
head or base of a recent open PR, or when it points at the same commit as a
non-generated branch such as main, since its age cannot be told from the
commit date in that case.

Uses the same environment variables as the E2E suite. A target is skipped
when its token is not set.

  github: TEST_GITHUB_API_URL, TEST_GITHUB_TOKEN,
          TEST_GITHUB_REPO_OWNER_GITHUBAPP, TEST_GITHUB_REPO_OWNER_WEBHOOK
  ghe:    TEST_GITHUB_SECOND_API_URL, TEST_GITHUB_SECOND_TOKEN,
          TEST_GITHUB_SECOND_REPO_OWNER_GITHUBAPP,
          TEST_GITHUB_SECOND_WEBHOOK_ORG, TEST_GITHUB_SECOND_WEBHOOK_TOKEN

Examples:
    # Dry-run (default), show what would be cleaned up:
    ./hack/cleanup-github-e2e.py

    # Actually clean up, GHE only:
    ./hack/cleanup-github-e2e.py --target ghe --force
"""

import argparse
import json
import os
import re
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass, field
from datetime import UTC, datetime, timedelta

BRANCH_RE = re.compile(
    r"^(pac-e2e-(test|ns|push)|incoming-branch|temp-base-branch)-[a-z0-9]{5}$"
)
REPO_RE = re.compile(r"^pac-e2e-test-[a-z0-9]{5}$")

BRANCHES_QUERY = """
query($owner: String!, $name: String!, $cursor: String) {
  repository(owner: $owner, name: $name) {
    refs(refPrefix: "refs/heads/", first: 100, after: $cursor) {
      pageInfo { hasNextPage endCursor }
      nodes { name target { oid ... on Commit { committedDate } } }
    }
  }
}
"""


class APIError(Exception):
    pass


def rate_limit_wait(status: int, headers, body: str, attempt: int) -> int | None:
    """Seconds to wait before retrying a rate-limited request, or None.

    Follows GitHub's guidance: Retry-After first, then X-RateLimit-Reset when
    the primary quota is used up, else exponential backoff from one minute
    for secondary limits, which may come without either header.
    """
    if status not in (403, 429):
        return None
    if retry_after := headers.get("Retry-After"):
        return int(retry_after)
    if headers.get("X-RateLimit-Remaining") == "0" and headers.get("X-RateLimit-Reset"):
        return max(int(headers["X-RateLimit-Reset"]) - int(time.time()), 0) + 1
    if status == 429 or "secondary rate limit" in body.lower():
        return 60 * 2**attempt
    return None


class Client:
    def __init__(self, host: str, token: str):
        host = re.sub(r"^https?://", "", host).rstrip("/")
        if host == "api.github.com":
            self.api_url = "https://api.github.com"
            self.graphql_url = "https://api.github.com/graphql"
        else:
            self.api_url = f"https://{host}/api/v3"
            self.graphql_url = f"https://{host}/api/graphql"
        self.token = token

    def request(self, method: str, url: str, body: dict | None = None):
        if not url.startswith("https://"):
            url = self.api_url + url
        data = json.dumps(body).encode() if body is not None else None
        for attempt in range(5):
            req = urllib.request.Request(url, data=data, method=method)
            req.add_header("Authorization", f"Bearer {self.token}")
            req.add_header("Accept", "application/vnd.github+json")
            if data is not None:
                req.add_header("Content-Type", "application/json")
            try:
                with urllib.request.urlopen(req, timeout=60) as resp:
                    raw = resp.read()
                    payload = json.loads(raw) if raw else None
                    return payload, resp.headers
            except urllib.error.HTTPError as exc:
                detail = exc.read().decode(errors="replace")
                wait = rate_limit_wait(exc.code, exc.headers, detail, attempt)
                if wait is not None and attempt < 4:
                    print(f"    rate limited, waiting {wait}s", file=sys.stderr)
                    time.sleep(wait)
                    continue
                if exc.code >= 500 and attempt < 4:
                    time.sleep(2**attempt)
                    continue
                raise APIError(f"{method} {url}: {exc.code} {detail[:200]}") from exc
            except urllib.error.URLError as exc:
                if attempt < 4:
                    time.sleep(2**attempt)
                    continue
                raise APIError(f"{method} {url}: {exc.reason}") from exc
        raise APIError(f"{method} {url}: too many retries")

    def paginate(self, path: str) -> list[dict]:
        sep = "&" if "?" in path else "?"
        url = f"{path}{sep}per_page=100"
        items: list[dict] = []
        while url:
            page, headers = self.request("GET", url)
            items.extend(page)
            url = ""
            for link in (headers.get("Link") or "").split(","):
                if 'rel="next"' in link:
                    url = link[link.index("<") + 1 : link.index(">")]
        return items

    def graphql(self, query: str, variables: dict) -> dict:
        payload, _ = self.request(
            "POST", self.graphql_url, {"query": query, "variables": variables}
        )
        if payload.get("errors"):
            raise APIError(f"GraphQL: {payload['errors']}")
        return payload["data"]


@dataclass
class Target:
    name: str
    client: Client
    repos: list[str]
    webhook_org: str = ""
    webhook_client: Client | None = None


@dataclass
class Stats:
    found: int = 0
    done: int = 0
    errors: list[str] = field(default_factory=list)


def parse_time(value: str) -> datetime:
    return datetime.fromisoformat(value)


def build_targets(selected: str) -> list[Target]:
    targets = []
    if selected in ("all", "github"):
        token = os.getenv("TEST_GITHUB_TOKEN", "")
        repos = [
            r
            for r in (
                os.getenv("TEST_GITHUB_REPO_OWNER_GITHUBAPP", ""),
                os.getenv("TEST_GITHUB_REPO_OWNER_WEBHOOK", ""),
            )
            if r
        ]
        if token and repos:
            client = Client(os.getenv("TEST_GITHUB_API_URL", "api.github.com"), token)
            targets.append(Target("github", client, repos))
        else:
            print("Skipping github: TEST_GITHUB_TOKEN or repos not set.")
    if selected in ("all", "ghe"):
        host = os.getenv("TEST_GITHUB_SECOND_API_URL", "")
        token = os.getenv("TEST_GITHUB_SECOND_TOKEN", "")
        repo = os.getenv("TEST_GITHUB_SECOND_REPO_OWNER_GITHUBAPP", "")
        if host and token and repo:
            target = Target("ghe", Client(host, token), [repo])
            webhook_token = os.getenv("TEST_GITHUB_SECOND_WEBHOOK_TOKEN", "")
            target.webhook_org = os.getenv("TEST_GITHUB_SECOND_WEBHOOK_ORG", "")
            if target.webhook_org and webhook_token:
                target.webhook_client = Client(host, webhook_token)
            targets.append(target)
        else:
            print(
                "Skipping ghe: TEST_GITHUB_SECOND_API_URL, TEST_GITHUB_SECOND_TOKEN "
                "or TEST_GITHUB_SECOND_REPO_OWNER_GITHUBAPP not set."
            )
    return targets


def list_branches(client: Client, repo: str) -> list[dict]:
    owner, name = repo.split("/", 1)
    branches, cursor = [], None
    while True:
        data = client.graphql(
            BRANCHES_QUERY, {"owner": owner, "name": name, "cursor": cursor}
        )
        refs = data["repository"]["refs"]
        branches.extend(refs["nodes"])
        if not refs["pageInfo"]["hasNextPage"]:
            return branches
        cursor = refs["pageInfo"]["endCursor"]


def show(label: str, items: list[str], verbose: bool) -> None:
    print(f"  {label}: {len(items)}")
    shown = items if verbose else items[:5]
    for item in shown:
        print(f"    {item}")
    if len(items) > len(shown):
        print(f"    ... {len(items) - len(shown)} more (use --verbose)")


def act(stats: Stats, items: list, describe, call, force: bool, sleep: float) -> None:
    stats.found += len(items)
    if not force:
        return
    for item in items:
        try:
            call(item)
            stats.done += 1
        except APIError as exc:
            stats.errors.append(f"{describe(item)}: {exc}")
        time.sleep(sleep)


def clean_repo(
    client: Client, repo: str, cutoff: datetime, args, stats: dict[str, Stats]
) -> None:
    print(f"\n{repo}")
    info, _ = client.request("GET", f"/repos/{repo}")
    if not info.get("permissions", {}).get("push"):
        if args.force:
            stats["prs"].errors.append(f"{repo}: token has no push access, skipped")
            print("  token has no push access, skipping")
            return
        print("  WARNING: token has no push access, --force would skip this repo")

    prs = client.paginate(f"/repos/{repo}/pulls?state=open")
    recent = [p for p in prs if parse_time(p["created_at"]) >= cutoff]
    in_use = {p["head"]["ref"] for p in recent} | {p["base"]["ref"] for p in recent}
    old_prs = [
        p
        for p in prs
        if parse_time(p["created_at"]) < cutoff
        and p["head"]["repo"]
        and p["head"]["repo"]["full_name"] == repo
        and BRANCH_RE.match(p["head"]["ref"])
    ]

    branches = list_branches(client, repo)
    fixed_shas = {
        b["target"]["oid"] for b in branches if not BRANCH_RE.match(b["name"])
    }
    old_branches = [
        b
        for b in branches
        if BRANCH_RE.match(b["name"])
        and b["name"] not in in_use
        and b["target"]["oid"] not in fixed_shas
        and b["target"].get("committedDate")
        and parse_time(b["target"]["committedDate"]) < cutoff
    ]

    print(f"  open PRs: {len(prs)}, branches: {len(branches)}")
    show(
        "PRs to close",
        [f"#{p['number']} {p['head']['ref']} ({p['created_at']})" for p in old_prs],
        args.verbose,
    )
    show(
        "branches to delete",
        [f"{b['name']} ({b['target']['committedDate']})" for b in old_branches],
        args.verbose,
    )

    act(
        stats["prs"],
        old_prs,
        lambda p: f"{repo}#{p['number']}",
        lambda p: client.request(
            "PATCH", f"/repos/{repo}/pulls/{p['number']}", {"state": "closed"}
        ),
        args.force,
        args.sleep,
    )
    act(
        stats["branches"],
        old_branches,
        lambda b: f"{repo}:{b['name']}",
        lambda b: client.request(
            "DELETE",
            f"/repos/{repo}/git/refs/heads/{urllib.parse.quote(b['name'])}",
        ),
        args.force,
        args.sleep,
    )


def clean_webhook_org(
    client: Client, org: str, cutoff: datetime, args, stats: Stats
) -> None:
    print(f"\n{org} (webhook org)")
    repos = client.paginate(f"/orgs/{org}/repos?type=all")
    old = [
        r
        for r in repos
        if REPO_RE.match(r["name"]) and parse_time(r["created_at"]) < cutoff
    ]
    print(f"  repositories: {len(repos)}")
    show(
        "repositories to delete",
        [f"{r['name']} ({r['created_at']})" for r in old],
        args.verbose,
    )
    act(
        stats,
        old,
        lambda r: r["full_name"],
        lambda r: client.request("DELETE", f"/repos/{r['full_name']}"),
        args.force,
        args.sleep,
    )


def main() -> None:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument(
        "--target",
        choices=["all", "github", "ghe"],
        default="all",
        help="Which forge to clean up (default: all)",
    )
    parser.add_argument(
        "--hours",
        type=int,
        default=24,
        help="Only clean up items older than this many hours (default: 24)",
    )
    parser.add_argument(
        "--sleep",
        type=float,
        default=1.0,
        help="Seconds to wait between write calls, GitHub advises at least 1 (default: 1)",
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help="Actually close and delete (default is dry-run)",
    )
    parser.add_argument(
        "--verbose", action="store_true", help="List every item, not a sample"
    )
    args = parser.parse_args()

    cutoff = datetime.now(tz=UTC) - timedelta(hours=args.hours)
    stats = {"prs": Stats(), "branches": Stats(), "repositories": Stats()}

    targets = build_targets(args.target)
    if not targets:
        print("ERROR: no target configured.", file=sys.stderr)
        sys.exit(1)

    failed = False
    for target in targets:
        print(
            f"\n=== {target.name} ({target.client.api_url}), older than {cutoff:%Y-%m-%d %H:%M} UTC"
        )
        for repo in target.repos:
            try:
                clean_repo(target.client, repo, cutoff, args, stats)
            except APIError as exc:
                print(f"  ERROR: {exc}", file=sys.stderr)
                failed = True
        if target.webhook_client:
            try:
                clean_webhook_org(
                    target.webhook_client,
                    target.webhook_org,
                    cutoff,
                    args,
                    stats["repositories"],
                )
            except APIError as exc:
                print(f"  ERROR: {exc}", file=sys.stderr)
                failed = True

    print()
    for kind, stat in stats.items():
        if args.force:
            print(
                f"{kind}: {stat.done}/{stat.found} cleaned up, {len(stat.errors)} error(s)"
            )
        else:
            print(f"{kind}: {stat.found} to clean up")
        for err in stat.errors:
            print(f"  ERROR {err}", file=sys.stderr)
            failed = True
    if not args.force:
        print("\nDry-run mode. Pass --force to close and delete.")
    sys.exit(1 if failed else 0)


if __name__ == "__main__":
    main()
